function populationTaxState(){return state.populationTax||{tax:0,carry:{},history:[],fund:{metal:0,crystal:0,eonium:0},canView:false,canEdit:false};}
function localPopulationTaxRoles(){ensureGalaxyPolitics();const ruler=state.galaxy.find(p=>p.player)?.ruler||'A. Commander';return {canView:state.politics.gc===ruler||Object.values(state.politics.ministers).includes(ruler),canEdit:state.politics.ministers.development===ruler};}
function populationTaxHTML(){const d=populationTaxState(),roles=state.centralPlayerId?d:localPopulationTaxRoles();if(!roles.canView)return '';const members=d.planets||state.galaxy.filter(p=>!p.exiled&&galaxyOf(p.coords)===homeGalaxy()).map(p=>({id:p.id,name:p.name,population:p.player?state.population:(p.population??p.publicPopulation??1000)})),history=d.history||[],rate=d.tax||0;return '<section class="panel population-tax"><div class="ph"><div class="pt">DEVELOPMENT MINISTRY · POPULATION TAX</div><span class="meta">'+(roles.canEdit?'MINISTER CONTROLS':'READ ONLY')+'</span></div><div class="population-kpis"><article><small>Ordinary resident levy</small><b>5 / 24 ticks maximum</b><span>Per planet · rolling collection window</span></article><article><small>Configured levy</small><b>'+rate+' residents / 24 ticks</b><span>'+(rate?'Accrues across newly settled ticks':'Ordinary levy disabled')+'</span></article><article><small>Full housing exception</small><b>Unused growth</b><span>Converted without removing existing residents</span></article><article><small>Conversion / resident</small><b>6 M · 4 C · 2 E</b><span>Galaxy Fund receives the resources</span></article></div><div class="controls"><label for="populationTaxRate">Residents per planet / 24 ticks</label><select id="populationTaxRate" '+(roles.canEdit?'':'disabled')+'>'+[0,1,2,3,4,5].map(n=>'<option value="'+n+'" '+(rate===n?'selected':'')+'>'+n+' residents / 24 ticks'+(n===0?' · ordinary levy off':'')+'</option>').join('')+'</select><button class="btn primary" data-population-tax '+(roles.canEdit?'':'disabled')+'>CONFIRM TAX</button></div><div class="note">Ordinary collection removes at most five actual residents from each planet in any rolling 24 ticks. Taxed in case of full pop: otherwise lost potential growth is converted separately into Galaxy Fund resources, with no existing residents removed and no five-resident cap on that growth. Only a planet’s newly reported ticks settle its levy. Unused growth is converted even when the ordinary levy is set to zero. No equal-share arrears are collected.</div><div class="table-wrap"><table class="table"><thead><tr><th>Planet</th><th>Residents</th><th>Ordinary taxed · last 24 ticks</th><th>Full-housing growth converted</th></tr></thead><tbody>'+members.map(p=>'<tr><td>'+esc(p.name)+'</td><td>'+nfmt(p.population)+'</td><td>'+(Number.isFinite(p.removedInWindow)?nfmt(p.removedInWindow)+' / 5':'Not reported')+'</td><td>'+(Number.isFinite(p.overflowTotal)?nfmt(p.overflowTotal):'See recorded reports')+'</td></tr>').join('')+'</tbody></table></div><details class="spaceport-history"><summary>Recorded population tax reports</summary>'+populationTaxHistoryHTML(history)+'</details></section>';}
async function refreshGalaxyDevelopment(){if(document.hidden)return;if(!state.centralPlayerId||window.isStaffWorkspace||!planetDirectoryReady)return;try{const requestedGalaxy=homeGalaxy();const d=await centralDirectoryRequest('/api/galaxy-development');if(homeGalaxy()!==requestedGalaxy||d.galaxy!==requestedGalaxy)return;ensureGalaxyPolitics();if(d.generation!==(state.centralResetGeneration||0))return;state.populationTax=d;state.galaxyFundTradeReceipts=d.trades||[];state.galaxyFund={...d.fund,log:(d.log||[]).map(x=>({text:x.text,tick:state.tick}))};state.politics.banner=d.banner||'Galaxy '+displayCoords(homeGalaxy());state.politics.message=d.message||'';state.politics.allowedFund={metal:true,crystal:true,eonium:true,...(d.allowedFund||{})};state.politics.votesToExile=d.exileVotes||[];state.politics.exileCount=(d.exileVotes||[]).filter(v=>v.status==="approved"&&v.window===Math.floor(state.tick/200)).length;state.politics.gc=d.gc;state.politics.ministers={communication:'',development:'',war:'',economics:'',scanner:'',...d.ministers};const counts={};for(const name of Object.values(d.votes||{}))counts[name]=(counts[name]||0)+1;state.politics.votes=counts;ensureGalaxyPolitics();renderGalaxyFund();save();if(document.querySelector('#page-politics.active'))renderPolitics();const block=document.getElementById('populationDetailBlock');if(block&&document.querySelector('#page-population.active'))block.innerHTML=populationDetailHTML()+governmentTaxRegisterHTML();}catch{}}
async function centralPoliticsAction(action,exileId){try{ensureGalaxyPolitics();const names=new Set(politicsPlanets().map(p=>p.ruler));if(action==='vote'&&!names.has(document.getElementById('gcVote').value))throw new Error('Choose a planet in your own galaxy.');if(action==='ministers'&&[...document.querySelectorAll('[data-minister]')].some(e=>e.value&&!names.has(e.value)))throw new Error('Ministers must belong to your own galaxy.');const payload={action,generation:state.centralResetGeneration||0};if(action==='approveExile'){payload.id=exileId;}else if(action==='exile'){payload.id=state.pendingExileRequest||(state.pendingExileRequest=crypto.randomUUID());payload.target=document.getElementById('exileTarget').value;payload.reason=document.getElementById('exileReason').value;}else if(action==='vote')payload.target=document.getElementById('gcVote').value;else if(action==='message'){payload.banner=document.getElementById('galaxyName').value;payload.message=document.getElementById('politicsMessage').value;}else if(action==='fund'){payload.allowedFund=Object.fromEntries([...document.querySelectorAll('[data-fundallow]')].map(e=>[e.dataset.fundallow,e.checked]));}else{payload.ministers={};document.querySelectorAll('[data-minister]').forEach(e=>payload.ministers[e.dataset.minister]=e.value);}await centralDirectoryRequest('/api/galaxy-development',payload);if(action==='exile')delete state.pendingExileRequest;await refreshGalaxyDevelopment();notify(({exile:'Shared exile proposal recorded.',approveExile:'Minister approval recorded.',vote:'Galaxy vote recorded.',ministers:'Minister appointments updated.',message:'Galaxy name and message saved.',fund:'Donation resource policy saved.'})[action]);}catch(e){notify(e.message,true);}}
async function setPopulationTax(){const rate=Number(document.getElementById('populationTaxRate')?.value);if(!Number.isInteger(rate)||rate<0||rate>5)return notify('Choose 0–5 residents per planet per 24 ticks.',true);if(state.centralPlayerId){try{await centralDirectoryRequest('/api/galaxy-development',{action:'tax',rate,generation:state.centralResetGeneration||0});await refreshGalaxyDevelopment();notify('Population tax set to '+rate+' residents per planet per 24 ticks.');}catch(e){notify(e.message,true);}return;}if(!localPopulationTaxRoles().canEdit)return notify('Only the Minister of Development can change population tax.',true);state.populationTax={...populationTaxState(),tax:rate};addNews('Minister of Development set population tax to '+rate+' residents per planet per 24 ticks.','info');state.news[0].category='POLITICS';update();}
function processPopulationTaxTick(){ensureGalaxyPolitics();const d=populationTaxState(),home=state.galaxy.find(p=>p.player);if(!home)return;const tick=state.tick,prior=d.ownTax||{},fresh=prior.policyVersion!==2,own={...prior,policyVersion:2,rollingCap:5,windowTicks:24,carry:fresh?0:(prior.carry||0),overflowCarry:fresh?0:(prior.overflowCarry||0),history:fresh?[]:(prior.history||[])};if(own.lastSettledTick>=tick)return;const rate=Math.max(0,Math.min(5,Math.floor(d.tax||0))),events=own.history.filter(h=>h.tick>tick-24&&h.tick<=tick),used=events.reduce((n,h)=>n+(h.removed||0),0),due=own.carry+rate/24,removed=Math.min(Math.max(0,Math.floor(state.population)),Math.max(0,5-used),Math.floor(due+1e-9));own.carry=Math.max(0,due-Math.floor(due+1e-9));const receipt=state.populationGrowthReceipt,full=receipt?.tick===tick&&receipt.fullAtStart===true,potential=full?Math.max(0,Number(receipt.potentialGrowth)||0):0,overflowDue=own.overflowCarry+potential,overflowConverted=full?Math.floor(overflowDue+1e-9):0;own.overflowCarry=full?Math.max(0,overflowDue-overflowConverted):own.overflowCarry;state.population=Math.max(0,state.population-removed);home.population=state.population;home.publicPopulation=state.population;const converted=removed+overflowConverted,income={metal:converted*6,crystal:converted*4,eonium:converted*2},entry={policyVersion:2,planetId:home.id,tick,rate,removed,overflowConverted,converted,income,population:state.population,potentialGrowth:potential,fullHousing:full,skippedTicks:Math.max(0,tick-(own.lastSettledTick||tick)-1)};own.history=[entry,...own.history].slice(0,96);own.rate=rate;own.lastSettledTick=tick;own.removedInWindow=used+removed;own.ordinaryTotal=(own.ordinaryTotal||0)+removed;own.total=own.ordinaryTotal;own.overflowTotal=(own.overflowTotal||0)+overflowConverted;own.convertedTotal=own.ordinaryTotal+own.overflowTotal;own.income={metal:own.convertedTotal*6,crystal:own.convertedTotal*4,eonium:own.convertedTotal*2};d.ownTax=own;d.history=[entry,...(fresh?[]:d.history||[])].slice(0,96);d.carry={[home.id]:own.carry};d.fund=d.fund||{};for(const k of Object.keys(RES)){d.fund[k]=(d.fund[k]||0)+income[k];state.galaxyFund[k]=(state.galaxyFund[k]||0)+income[k];}state.populationTax=d;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-population-tax],[data-achievement-category]');if(!b)return;if(b.hasAttribute('data-population-tax'))setPopulationTax();if(b.dataset.achievementCategory){state.questView="category";state.questCategory=b.dataset.achievementCategory;applyQuestTab();save();}});
setInterval(refreshGalaxyDevelopment,15000);setTimeout(refreshGalaxyDevelopment,2500);

function governmentTaxRegisterHTML(){return '';}

async function centralGalaxyFundAction(action,selection){const resource=selection?.resource??document.getElementById(action==='deposit'?'gfundDepositResource':'gfundPayoutResource')?.value,amount=Number(selection?.amount??document.getElementById(action==='deposit'?'gfundDepositAmount':'gfundPayoutAmount')?.value),targetId=selection?.target??document.getElementById('gfundTarget')?.value;try{if(!await syncOwnedColony(true))throw Error('Refresh your colony before a fund transaction.');const result=await centralDirectoryRequest('/api/galaxy-development',{action,resource,amount,targetId,generation:state.centralResetGeneration||0});if(action==='deposit')state.resources=result.resources;recordOrderConfirmation('galaxy-fund-'+action,{resource,amount,targetId});await refreshAfterCentralWrite();await refreshGalaxyDevelopment();update();}catch(e){notify(e.message,true);}}

function distributionControlsHTML(){return '<section class="panel galaxy-distribution"><div class="ph"><div class="pt">GALAXY DISTRIBUTION CONTROL</div><span class="meta">AUTOMATIC AT TICK 12</span></div><p class="note">New commands enter starting galaxies. Shuffle redistributes all enrolled players into regular galaxies, with ten player slots per galaxy and one hundred galaxies per cluster. Empty galaxies and clusters are created as needed.</p><div id="distributionStatus" class="controls">Retrieving distribution status…</div><div class="controls"><button class="btn" data-distribution-refresh>REFRESH STATUS</button><button class="btn warn" data-distribution-shuffle>REVIEW MANUAL SHUFFLE</button></div></section>';}
async function refreshDistributionControls(){if(document.hidden)return;if(!window.isGameAdmin)return;const e=document.getElementById('distributionStatus');if(!e)return;try{const d=await centralDirectoryRequest('/api/admin/shuffle');e.textContent=d.players+' players · '+d.galaxies+' galaxies · '+d.clusters+' clusters · '+(d.shuffled?'Redistributed at tick '+d.atTick:'Starting galaxies · redistribution at tick 12');}catch(error){e.textContent=error.message;}}
async function manualGalaxyShuffle(){if(!window.isGameAdmin)return;if(!confirm('Redistribute all enrolled players into new galaxies now? Planet assets are retained.'))return;try{const d=await centralDirectoryRequest('/api/admin/shuffle',{confirmation:'SHUFFLE'});await refreshAfterCentralWrite();await refreshDistributionControls();notify('Shuffle complete: '+d.planets+' players in '+d.galaxies+' galaxies and '+d.clusters+' clusters.');}catch(e){notify(e.message,true);}}
document.addEventListener('click',e=>{if(e.target.closest('[data-distribution-refresh]'))refreshDistributionControls();if(e.target.closest('[data-distribution-shuffle]'))manualGalaxyShuffle();});setInterval(refreshDistributionControls,15000);

let allianceWelcomeCreate='',allianceWelcomeRecover='';
function prepareAllianceWelcome(){const create=document.getElementById('allianceCreatePanel'),recover=document.querySelector('#page-alliance .alliance-restore-panel');if(create&&!create.closest('#allianceContent')){create.hidden=false;create.open=true;allianceWelcomeCreate=create.outerHTML;create.remove();}if(recover&&!recover.closest('#allianceContent')){allianceWelcomeRecover=recover.outerHTML;recover.remove();}const page=document.getElementById('page-alliance');if(page)page.dataset.membership=state.alliance.name==='Unaffiliated'?'unaffiliated':'member';}
function allianceWelcomeHTML(){return '<section class="alliance-welcome-charter"><span class="revenue-seal">✦</span><div><small>INTERSTELLAR CHARTER OFFICE · UNAFFILIATED COMMAND</small><h2>Your place among the alliances</h2><p>Request admission, establish a new alliance, or recover your registered command. Applications appear as pending Recruits; approved recruits gain access to their alliance overview.</p></div></section><div class="alliance-welcome-grid"><section class="panel"><div class="ph"><div class="pt">01 · JOIN ALLIANCE</div></div><div class="settings-body"><p>All known alliances are listed below. Choose an active alliance and send a recruitment request.</p><div id="knownAllianceList">Retrieving the alliance registry…</div><label for="joinAllianceTarget">Requested alliance</label><select id="joinAllianceTarget"></select><label for="joinAllianceMessage">Introduction to High Command</label><textarea id="joinAllianceMessage" rows="3" maxlength="1000" placeholder="Introduce your colony and explain why you want to join."></textarea><button class="btn primary" data-alliance-apply>REQUEST TO JOIN AS RECRUIT</button><p id="allianceJoinStatus" role="status"></p></div></section><section class="panel"><div class="ph"><div class="pt">02 · CREATE ALLIANCE</div></div>'+allianceWelcomeCreate.replace('Five unassigned practice planets are added when capacity allows; assign them from Administration → Planets.','No dummy planets are created.')+'</section><section class="panel"><div class="ph"><div class="pt">03 · RECOVER ALLIANCE</div></div>'+allianceWelcomeRecover+'</section></div>';}
async function loadKnownAlliances(){const list=document.getElementById('knownAllianceList'),select=document.getElementById('joinAllianceTarget');if(!list||!select)return;try{const d=await centralDirectoryRequest('/api/alliance-applications');list.innerHTML=d.alliances.length?d.alliances.map(a=>'<article class="known-alliance"><b>'+esc(a.name)+' '+(a.tag?'['+esc(a.tag)+']':'')+'</b><small>'+a.members+' members · '+(a.archived?'RESERVED · RECOVERY':a.pending?'RECRUIT REQUEST PENDING':a.open?'RECRUITING':'CLOSED')+'</small><p>'+esc(a.recruitmentMessage)+'</p></article>').join(''):'<p>No alliances registered yet. Establish the first charter.</p>';select.innerHTML=d.alliances.filter(a=>!a.archived&&a.open&&!a.pending&&a.members<40).map(a=>'<option value="'+esc(a.name)+'">'+esc(a.name)+'</option>').join('');const button=document.querySelector('[data-alliance-apply]');if(button)button.disabled=!select.options.length;}catch(e){list.textContent=e.message;}}
async function applyToAlliance(){const alliance=document.getElementById('joinAllianceTarget')?.value,message=document.getElementById('joinAllianceMessage')?.value||'';if(!alliance)return notify('Choose an alliance that is recruiting.',true);try{await centralDirectoryRequest('/api/alliance-applications',{action:'apply',alliance,message,generation:state.centralResetGeneration||0});await loadKnownAlliances();document.getElementById('allianceJoinStatus').textContent='Request delivered to '+alliance+'. Recruit · awaiting approval.';notify('Recruit application sent.');}catch(e){notify(e.message,true);}}
async function centralRecruitmentDecision(action,button){try{await centralDirectoryRequest('/api/alliance-applications',{action,applicationId:button.dataset.applicant,generation:state.centralResetGeneration||0});await refreshAfterCentralWrite();notify(action==='accept'?'Applicant accepted as Recruit.':'Application declined.');}catch(e){notify(e.message,true);}}
async function refreshAllianceEconomy(){if(document.hidden)return;if(!state.centralPlayerId||state.alliance.name==='Unaffiliated'||window.isStaffWorkspace)return;try{const d=await centralDirectoryRequest('/api/alliance-economy');if(d.alliance!==state.alliance.name)return;state.allianceEconomy=d;if(allianceTab==='home'&&document.querySelector('#page-alliance.active'))renderAlliance();}catch{}}
function allianceEconomyOverviewHTML(){const d=state.allianceEconomy||{totals:Object.fromEntries(Object.keys(RES).map(k=>[k,{gross:0,net:0,finance:0,population:0,refineries:0}])),reported:0,planets:state.alliance.members.length,population:0,biodomes:0,asteroids:0};const signals=[...state.news.filter(x=>newsCategory(x)==='ALLIANCE').map(x=>({tick:x.tick,text:x.text,type:x.type})),...(state.alliance.log||[]).map(x=>({tick:x.tick,text:x.msg||x.text,type:'info'}))].filter(x=>x.text).sort((a,b)=>(b.tick||0)-(a.tick||0)),seen=new Set(),news=signals.filter(x=>{const key=x.tick+'|'+x.text;if(seen.has(key))return false;seen.add(key);return true;}).slice(0,8);return '<section class="alliance-overview-charter"><span class="revenue-seal">✦</span><div><small>ALLIANCE COMMAND · STRATEGIC OVERVIEW</small><h2>'+esc(state.alliance.name)+'</h2><p>'+esc(state.alliance.motd||state.alliance.description||'United colonies. Shared resources. Coordinated command.')+'</p></div><span class="tag">'+state.alliance.members.length+' MEMBERS</span></section><div class="alliance-overview-grid"><section class="panel alliance-news-prominent"><div class="ph"><div class="pt">ALLIANCE NEWS & COMMAND SIGNALS</div><span class="meta">LATEST TRANSMISSIONS</span></div>'+ (news.map(x=>'<article><span class="tag '+(x.type==='warn'?'red':'blue')+'">T'+String(x.tick||1).padStart(3,'0')+'</span><p>'+esc(x.text)+'</p></article>').join('')||'<div class="empty">Awaiting the first alliance transmission.</div>')+'</section><section class="panel alliance-economy-summary"><div class="ph"><div class="pt">ALLIANCE ECONOMY</div><span class="meta">'+d.reported+' / '+d.planets+' REPORTS</span></div><div class="alliance-kpis">'+[['Population',d.population],['Biodomes',d.biodomes],['Asteroids',d.asteroids],['Alliance tax',(state.alliance.tax||0)+'%']].map(([k,v])=>'<div class="alliance-kpi"><small>'+k+'</small><b>'+(typeof v==='number'?nfmt(v):v)+'</b></div>').join('')+'</div><div class="alliance-income-cards">'+Object.keys(RES).map(k=>{const n=d.totals[k];return '<article><span class="income-resource-art '+k+'"></span><div><small>'+RES[k].label+' NET / TICK</small><b>'+nfmt(n.net)+'</b><small>Gross '+nfmt(n.gross)+' · Alliance tax '+nfmt(n.gross-n.net)+'</small></div></article>';}).join('')+'</div><div class="table-wrap"><table><thead><tr><th>Income contribution</th>'+Object.keys(RES).map(k=>'<th>'+RES[k].label+'</th>').join('')+'</tr></thead><tbody>'+[['refineries','Refinery base'],['finance','Finance Centres'],['population','Population bonus']].map(([key,label])=>'<tr><td>'+label+'</td>'+Object.keys(RES).map(k=>'<td>'+nfmt(d.totals[k][key])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p class="note">Aggregated colony reports; missing reports are excluded. Contributions precede final multipliers and rounding. Total reserves: '+nfmt(totalRoids(state.alliance.fund))+' resources.</p></section></div><section class="panel"><div class="ph"><div class="pt">COMMANDER’S MESSAGE</div></div><div class="compose"><textarea id="allianceMessage">'+esc(state.alliance.message||'')+'</textarea><button class="btn primary" data-alliance="message">POST MESSAGE</button></div></section>';}
document.addEventListener('click',e=>{if(e.target.closest('[data-alliance-apply]'))applyToAlliance();});setInterval(refreshAllianceEconomy,30000);setTimeout(()=>{renderAlliance();refreshAllianceEconomy();},2000);

function decorateGamePages(){const artwork={overview:'/assets/planets/'+planetTypeFor(state).id+'.svg',population:'/assets/planets/'+planetTypeFor(state).id+'.svg',construction:'/assets/structures/lightFactory.svg',research:'/assets/structures/researchLab.svg',resources:'/assets/structures/metalRefinery.svg',universe:'/assets/planets/planet-03.svg',galaxy:'/assets/planets/planet-05.svg',politics:'/assets/structures/financeCenter.svg',galaxyFund:'/assets/structures/financeCenter.svg',waves:'/assets/structures/waveAmplifier.svg',covert:'/assets/planets/planet-32.svg',fleets:'/assets/structures/heavyFactory.svg',production:'/assets/structures/mediumFactory.svg',quests:'/assets/structures/biodome.svg',news:'/assets/structures/waveAmplifier.svg',bcalc:'/assets/structures/structureDefense.svg',mail:'/assets/structures/waveAmplifier.svg'};for(const [page,src] of Object.entries(artwork)){const head=document.querySelector('#page-'+page+'>.subhead');if(!head)continue;let art=head.querySelector('.page-section-art');if(!art){art=document.createElement('img');art.className='page-section-art';art.alt='';art.setAttribute('aria-hidden','true');head.append(art);}if(art.getAttribute('src')!==src)art.src=src;}}
setTimeout(decorateGamePages,2000);setInterval(decorateGamePages,15000);
function updateGalaxyFundTradeQuote(resource){for(const from of resource?[resource]:Object.keys(RES)){const to=document.getElementById('gfundTradeTo-'+from)?.value,n=Number(document.getElementById('gfundTradeAmount-'+from)?.value),out=document.getElementById('gfundTradeQuote-'+from);if(!out)continue;if(!RES[to]||from===to||!Number.isSafeInteger(n)||n<1){out.textContent='Choose a different resource and a positive whole amount.';continue;}out.textContent='Receive '+nfmt(n-Math.ceil(n*.01))+' '+to+' · Fee '+nfmt(Math.ceil(n*.01))+' (1%) to Universal Bank · Fund reserve '+nfmt(state.galaxyFund[to]||0);}}
async function exchangeGalaxyFund(from){if(window.galaxyFundTradeBusy||!RES[from])return;const to=document.getElementById('gfundTradeTo-'+from)?.value,amount=Number(document.getElementById('gfundTradeAmount-'+from)?.value),message=document.getElementById('gfundTradeMessage-'+from);if(!state.centralPlayerId||!RES[to]||from===to||!Number.isSafeInteger(amount)||amount<1)return notify('Choose a different resource and a positive whole amount for your registered planet.',true);const context={user:state.centralPlayerId,generation:state.centralResetGeneration||0,galaxy:homeGalaxy(),snapshot:state},valid=()=>state===context.snapshot&&state.centralPlayerId===context.user&&(state.centralResetGeneration||0)===context.generation&&homeGalaxy()===context.galaxy;window.galaxyFundTradeBusy=true;if(message)message.textContent='Settling exchange…';document.querySelectorAll('[data-gfund-trade]').forEach(b=>b.disabled=true);try{if(!await syncOwnedColony(true))throw Error('Refresh your colony before trading.');if(!valid())throw Error('Your planet changed. Reopen the Galaxy Fund.');const fresh=await centralDirectoryRequest('/api/galaxy-development');if(!valid()||fresh.galaxy!==context.galaxy||fresh.generation!==context.generation)throw Error('Your galaxy changed. Refresh before trading.');const signature=[context.user,context.generation,context.galaxy,from,to,amount].join('|');let pending=state.pendingGalaxyFundTrade;if(!pending||pending.signature!==signature)pending=state.pendingGalaxyFundTrade={id:crypto.randomUUID(),signature};save();const result=await centralDirectoryRequest('/api/galaxy-development',{action:'trade',id:pending.id,from,to,amount,generation:context.generation,revision:fresh.revision});if(!valid())return;recordOrderConfirmation('galaxy-fund-trade',{id:pending.id,...result.trade});state.pendingGalaxyFundTrade=null;save();await refreshAfterCentralWrite();await refreshGalaxyDevelopment();}catch(error){if(valid()){if(message?.isConnected)message.textContent=error.message;notify(error.message,true);}}finally{window.galaxyFundTradeBusy=false;document.querySelectorAll('[data-gfund-trade]').forEach(b=>b.disabled=false);}}
document.addEventListener('click',event=>{const view=event.target.closest('[data-spaceport-view]');if(view){window.spaceportView=view.dataset.spaceportView;applySpaceportView();}const action=event.target.closest('[data-fund-section-open]');if(action){window.galaxyFundActionView=action.dataset.fundSectionOpen;applySpaceportView();}const exchange=event.target.closest('[data-gfund-trade]');if(exchange)void exchangeGalaxyFund(exchange.dataset.gfundTrade);});
document.addEventListener('input',event=>{if(event.target.dataset?.gfundTradeInput)updateGalaxyFundTradeQuote(event.target.dataset.gfundTradeInput);});
document.addEventListener('change',event=>{if(event.target.dataset?.gfundTradeInput)updateGalaxyFundTradeQuote(event.target.dataset.gfundTradeInput);});

function populationTaxHistoryHTML(history){return history.length?'<div class="table-wrap"><table class="table"><thead><tr><th>Tick</th><th>Residents removed</th><th>Unused growth converted</th><th>Metal / Crystal / Eonium</th></tr></thead><tbody>'+history.slice(0,24).map(h=>'<tr><td>'+nfmt(h.tick)+(h.skippedTicks?' · '+nfmt(h.skippedTicks)+' unobserved ticks not estimated':'')+'</td><td>'+nfmt(h.removed)+'</td><td>'+nfmt(h.overflowConverted)+'</td><td>'+nfmt(h.income?.metal)+' / '+nfmt(h.income?.crystal)+' / '+nfmt(h.income?.eonium)+'</td></tr>').join('')+'</tbody></table></div>':'<p class="note">No recorded population tax reports yet.</p>';}
function populationTaxReportHTML(){const d=populationTaxState(),own=d.ownTax?.policyVersion===2?d.ownTax:null,home=state.galaxy.find(p=>p.player),history=(own?.policyVersion===2?own.history||[]:[]).filter(h=>h.planetId===home?.id),rate=own?.rate??d.tax??0,normal=own?.removedInWindow,full=state.population>=populationCapacity(),potential=full?Math.max(0,Math.floor(Math.max(0,Number(populationGrowthRate())||0)+(Number.isFinite(own?.overflowCarry)&&own.overflowCarry>=0&&own.overflowCarry<1?own.overflowCarry:0)+1e-9)):0,recorded=history.reduce((a,h)=>({removed:a.removed+(h.removed||0),overflow:a.overflow+(h.overflowConverted||0),metal:a.metal+(h.income?.metal||0),crystal:a.crystal+(h.income?.crystal||0),eonium:a.eonium+(h.income?.eonium||0)}),{removed:0,overflow:0,metal:0,crystal:0,eonium:0});return '<div class="population-tax-report"><div class="population-kpis"><article><small>Ordinary taxed · last 24 ticks</small><b>'+(Number.isFinite(normal)?nfmt(normal)+' / 5':'Awaiting report')+'</b><span>Actual residents removed · limit five</span></article><article><small>Taxed in case of full pop</small><b>'+(full?'Full housing':'Housing available')+'</b><span>Unused growth only · existing residents retained</span></article><article><small>Projected unused growth conversion</small><b>'+nfmt(potential)+' resident-equivalents</b><span>'+nfmt(potential*6)+' M · '+nfmt(potential*4)+' C · '+nfmt(potential*2)+' E next tick; projection</span></article><article><small>'+(Number.isFinite(own?.ordinaryTotal)&&Number.isFinite(own?.overflowTotal)?'Total ordinary / growth conversions':'Recorded ordinary / growth conversions')+'</small><b>'+nfmt(own?.ordinaryTotal??recorded.removed)+' / '+nfmt(own?.overflowTotal??recorded.overflow)+'</b><span>Actual reports shown below; not a lifetime estimate</span></article><article><small>Recorded Galaxy Fund income</small><b>'+nfmt(recorded.metal)+' M · '+nfmt(recorded.crystal)+' C · '+nfmt(recorded.eonium)+' E</b><span>Ordinary levy plus full-housing growth</span></article></div><details class="spaceport-history"><summary>Population tax reports · ordinary and full housing</summary>'+populationTaxHistoryHTML(history)+'</details></div>';}
// SF-116: record actual pre-growth ecology for each observed tick, including catch-up.
function recordPopulationIncomeTick(){state.populationIncomeTicks=state.populationIncomeTicks||[];if(state.populationIncomeTicks.some(r=>r.tick===state.tick))return;state.populationIncomeTicks.push({tick:state.tick,population:Math.floor(state.population),biodomes:Math.floor(state.buildings.biodome||0),demography:Math.floor(state.research.demography||0),biodomeDamage:Math.floor(state.biodomeDamage||0)});}
